def transform(grid):
    # Reflect vertically by concatenating reversed rows, then original, then reversed rows;
    # reflect each row horizontally and concatenate with the original.
    rows = grid[::-1] + grid + grid[::-1]
    return [row[::-1] + row for row in rows]

